// AC: @trait-type ac-2
it('should warn when trait item is missing acceptance criteria', async () => {
  // Setup minimal kspec structure
  const kspecDir = path.join(tempDir, '.kspec');
  const modulesDir = path.join(kspecDir, 'modules');
  await fs.mkdir(modulesDir, { recursive: true });

  // Create manifest
  const manifest = {
    _ulid: '01TEST0000000000000000000',
    slugs: ['test-project'],
    title: 'Test Project',
    includes: ['modules/traits.yaml'],
  };
  await writeYamlFilePreserveFormat(path.join(kspecDir, 'test.yaml'), manifest);

  // Create trait without acceptance criteria
  const trait = {
    _ulid: '01TRAIT000000000000000000',
    slugs: ['test-trait'],
    title: 'Test Trait',
