            then: 'result',
          },
        ],
        description: 'First trait',
        _sourceFile: 'spec/traits.yaml',
      },
      {
        _ulid: '01TRAIT200000000000000000',
        slugs: ['trait-b'],
        title: 'Trait B',
        type: 'trait',
        tags: [],
        depends_on: [],
        implements: [],
        relates_to: [],
        tests: [],
        acceptance_criteria: [
          {
            id: 'ac-1',
            given: 'context',
            when: 'action',
            then: 'result',
          },
        ],
        description: 'Second trait',
        _sourceFile: 'spec/traits.yaml',
      },
      {
        _ulid: '01SPEC1000000000000000000',
