/**
 * Reference resolution system for @references.
 *
 * Handles resolution of @slug and @ulid references to actual items,
 * with proper error handling for not-found and ambiguous cases.
 */

import type { LoadedSpecItem, LoadedTask, AnyLoadedItem } from './yaml.js';
import type { LoadedMetaItem } from './meta.js';

// ============================================================
// TYPES
// ============================================================

/**
 * Successful resolution result
 * AC: @agent-definitions ac-agent-3
 */
export interface ResolveSuccess {
  ok: true;
  ulid: string;
  item: AnyLoadedItem | LoadedMetaItem;
  /** How the reference was matched */
  matchType: 'slug' | 'ulid-full' | 'ulid-prefix';
}

/**
 * Failed resolution - reference not found
 */
export interface ResolveNotFound {
  ok: false;
  error: 'not_found';
  ref: string;
}

/**
 * Failed resolution - ambiguous ULID prefix
 */
export interface ResolveAmbiguous {
  ok: false;
  error: 'ambiguous';
  ref: string;
  /** The matching ULIDs */
  candidates: string[];
}

/**
 * Failed resolution - duplicate slug
 */
export interface ResolveDuplicateSlug {
  ok: false;
  error: 'duplicate_slug';
  ref: string;
  /** The ULIDs that share this slug */
  candidates: string[];
}

export type ResolveResult =
  | ResolveSuccess
  | ResolveNotFound
  | ResolveAmbiguous
  | ResolveDuplicateSlug;

/**
 * Validation error for a single reference
 */
export interface RefValidationError {
  /** The reference string that failed */
  ref: string;
  /** Where this reference was found */
  sourceFile?: string;
  /** The item containing this reference */
  sourceUlid?: string;
  /** The field containing this reference */
  field: string;
  /** Error type */
  error: 'not_found' | 'ambiguous' | 'duplicate_slug';
  /** Additional context */
  message: string;
}

/**
 * Validation warning for a single reference
 */
export interface RefValidationWarning {
  /** The reference string */
  ref: string;
  /** Where this reference was found */
  sourceFile?: string;
  /** The item containing this reference */
  sourceUlid?: string;
  /** The field containing this reference */
  field: string;
  /** Warning type */
  warning: 'deprecated_target';
  /** Additional context */
  message: string;
}

// ============================================================
// REFERENCE INDEX
// ============================================================

/**
 * Index for efficient reference resolution.
 * Build once when loading the spec, then resolve many times.
 * AC: @agent-definitions ac-agent-3
 */
export class ReferenceIndex {
  /** slug → ULID mapping */
  private slugIndex = new Map<string, string[]>();

  /** ULID → item mapping */
  private ulidIndex = new Map<string, AnyLoadedItem | LoadedMetaItem>();

  /** All ULIDs for prefix matching */
  private allUlids: string[] = [];

  /**
   * Build index from loaded items and meta items
   * AC: @agent-definitions ac-agent-3
   */
  constructor(
    tasks: LoadedTask[],
    items: LoadedSpecItem[],
    metaItems: LoadedMetaItem[] = []
  ) {
    // Index tasks
    for (const task of tasks) {
      this.indexItem(task);
    }

    // Index spec items
    for (const item of items) {
      this.indexItem(item);
    }

    // Index meta items (agents, workflows, conventions, observations)
    // AC: @agent-definitions ac-agent-3
    for (const metaItem of metaItems) {
      this.indexMetaItem(metaItem);
    }

    // Sort ULIDs for consistent ordering
    this.allUlids.sort();
  }

  private indexItem(item: AnyLoadedItem): void {
    const ulid = item._ulid;

    // Index by ULID
    this.ulidIndex.set(ulid, item);
    this.allUlids.push(ulid);

    // Index by slugs
    for (const slug of item.slugs) {
      const existing = this.slugIndex.get(slug);
      if (existing) {
        existing.push(ulid);
      } else {
        this.slugIndex.set(slug, [ulid]);
      }
    }
  }

  /**
   * Index a meta item (agent, workflow, convention, observation)
   * Meta items use 'id' field as their slug
   * AC: @agent-definitions ac-agent-3
   */
  private indexMetaItem(item: LoadedMetaItem): void {
    const ulid = item._ulid;

    // Index by ULID
    this.ulidIndex.set(ulid, item);
    this.allUlids.push(ulid);

    // Index by id (acts like a slug for meta items)
    const metaItem = item as { id?: string };
    if (metaItem.id) {
      const existing = this.slugIndex.get(metaItem.id);
      if (existing) {
        existing.push(ulid);
      } else {
        this.slugIndex.set(metaItem.id, [ulid]);
      }
    }
  }

  /**
   * Resolve a reference to an item.
   *
   * Resolution order:
   * 1. Exact slug match
   * 2. Full ULID match
   * 3. ULID prefix match (must be unique)
   */
  resolve(ref: string): ResolveResult {
    // Strip @ prefix if present
    const cleanRef = ref.startsWith('@') ? ref.slice(1) : ref;
    const cleanRefLower = cleanRef.toLowerCase();

    // 1. Try slug match first
    const slugMatches = this.slugIndex.get(cleanRef);
    if (slugMatches) {
      if (slugMatches.length > 1) {
        return {
          ok: false,
          error: 'duplicate_slug',
          ref,
          candidates: slugMatches,
        };
      }
      const ulid = slugMatches[0];
      const item = this.ulidIndex.get(ulid)!;
      return { ok: true, ulid, item, matchType: 'slug' };
    }

    // 2. Try full ULID match
    const exactMatch = this.ulidIndex.get(cleanRef.toUpperCase());
    if (exactMatch) {
      return {
        ok: true,
        ulid: exactMatch._ulid,
        item: exactMatch,
        matchType: 'ulid-full',
      };
    }

    // 3. Try ULID prefix match
    const prefixMatches = this.allUlids.filter(ulid =>
      ulid.toLowerCase().startsWith(cleanRefLower)
    );

    if (prefixMatches.length === 0) {
      return { ok: false, error: 'not_found', ref };
    }

    if (prefixMatches.length > 1) {
      return {
        ok: false,
        error: 'ambiguous',
        ref,
        candidates: prefixMatches,
      };
    }

    const ulid = prefixMatches[0];
    const item = this.ulidIndex.get(ulid)!;
    return { ok: true, ulid, item, matchType: 'ulid-prefix' };
  }

  /**
   * Get an item by exact ULID (no resolution, direct lookup)
   */
  getByUlid(ulid: string): AnyLoadedItem | LoadedMetaItem | undefined {
    return this.ulidIndex.get(ulid);
  }

  /**
   * Get the minimum unique prefix for a ULID.
   * Returns the shortest prefix that uniquely identifies this ULID
   * among all indexed items.
   *
   * @param ulid The full ULID to shorten
   * @param minLength Minimum prefix length (default 8)
   * @returns Shortest unique prefix
   */
  shortUlid(ulid: string, minLength = 8): string {
    // Start with minimum length
    let length = minLength;

    while (length < ulid.length) {
      const prefix = ulid.slice(0, length);
      const matches = this.allUlids.filter(u =>
        u.toUpperCase().startsWith(prefix.toUpperCase())
      );

      if (matches.length === 1) {
        return prefix;
      }

      length++;
    }

    // Return full ULID if no shorter unique prefix found
    return ulid;
  }

  /**
   * Get all indexed ULIDs
   */
  getAllUlids(): string[] {
    return [...this.allUlids];
  }

  /**
   * Get all slugs and their mappings
   */
  getAllSlugs(): Map<string, string[]> {
    return new Map(this.slugIndex);
  }

  /**
   * Check if a slug exists
   */
  hasSlug(slug: string): boolean {
    return this.slugIndex.has(slug);
  }

  /**
   * Get count of indexed items
   */
  get size(): number {
    return this.ulidIndex.size;
  }
}

// ============================================================
// VALIDATION
// ============================================================

/**
 * Fields that contain references
 * AC: @agent-definitions ac-agent-3 - added_by for agent references
 * AC: @workflow-definitions ac-workflow-3 - meta_ref for workflow references
 * AC: @traits-field ac-1 - traits field contains refs to trait-type items
 */
const REF_FIELDS = [
  'depends_on',
  'blocked_by',
  'implements',
  'relates_to',
  'tests',
  'supersedes',
  'spec_ref',
  'context',
  'added_by', // Agent reference
  'author', // Agent reference
  'resolved_by', // Agent reference
  'workflow_ref', // Workflow reference
  'meta_ref', // Meta reference (workflow, agent, convention)
  'traits', // Trait references (AC: @traits-field ac-1)
];

/**
 * Check if an item is deprecated
 */
function isDeprecated(item: AnyLoadedItem | LoadedMetaItem): boolean {
  const obj = item as unknown as Record<string, unknown>;

  // Check for deprecated_in field (truthy value means deprecated)
  if ('deprecated_in' in obj && obj.deprecated_in) {
    return true;
  }

  // Check for maturity: deprecated status
  if ('status' in obj && obj.status && typeof obj.status === 'object') {
    const status = obj.status as Record<string, unknown>;
    if ('maturity' in status && status.maturity === 'deprecated') {
      return true;
    }
  }

  // Also check top-level maturity field (some items may have it there)
  if ('maturity' in obj && obj.maturity === 'deprecated') {
    return true;
  }

  return false;
}

/**
 * Extract all references from an item
 * AC: @agent-definitions ac-agent-3 - also checks nested notes for author refs
 */
function extractRefs(item: AnyLoadedItem): Array<{ field: string; ref: string }> {
  const refs: Array<{ field: string; ref: string }> = [];
  const obj = item as unknown as Record<string, unknown>;

  for (const field of REF_FIELDS) {
    const value = obj[field];

    if (typeof value === 'string' && value.startsWith('@')) {
      refs.push({ field, ref: value });
    } else if (Array.isArray(value)) {
      for (const v of value) {
        if (typeof v === 'string' && v.startsWith('@')) {
          refs.push({ field, ref: v });
        }
      }
    }
  }

  // Check nested notes for author references
  // AC: @agent-definitions ac-agent-3
  if ('notes' in obj && Array.isArray(obj.notes)) {
    for (const note of obj.notes) {
      if (note && typeof note === 'object' && 'author' in note) {
        const author = (note as { author?: string }).author;
        if (typeof author === 'string' && author.startsWith('@')) {
          refs.push({ field: 'notes[].author', ref: author });
        }
      }
    }
  }

  // Check nested todos for added_by references
  if ('todos' in obj && Array.isArray(obj.todos)) {
    for (const todo of obj.todos) {
      if (todo && typeof todo === 'object' && 'added_by' in todo) {
        const addedBy = (todo as { added_by?: string }).added_by;
        if (typeof addedBy === 'string' && addedBy.startsWith('@')) {
          refs.push({ field: 'todos[].added_by', ref: addedBy });
        }
      }
    }
  }

  return refs;
}

/**
 * Validation result with errors and warnings
 */
export interface RefValidationResult {
  errors: RefValidationError[];
  warnings: RefValidationWarning[];
}

/**
 * Validate all references in the spec.
 * Returns list of validation errors and warnings.
 */
export function validateRefs(
  index: ReferenceIndex,
  tasks: LoadedTask[],
  items: LoadedSpecItem[]
): RefValidationResult {
  const errors: RefValidationError[] = [];
  const warnings: RefValidationWarning[] = [];

  const allItems: AnyLoadedItem[] = [...tasks, ...items];

  for (const item of allItems) {
    const refs = extractRefs(item);
    const sourceFile = (item as LoadedTask | LoadedSpecItem)._sourceFile;

    // Track traits for duplicate detection (AC: @traits-field ac-5)
    const seenTraits = new Set<string>();

    for (const { field, ref } of refs) {
      const result = index.resolve(ref);

      if (!result.ok) {
        let message: string;

        switch (result.error) {
          case 'not_found':
            message = `Reference "${ref}" not found`;
            break;
          case 'ambiguous':
            message = `Reference "${ref}" is ambiguous, matches: ${result.candidates.join(', ')}`;
            break;
          case 'duplicate_slug':
            message = `Slug "${ref}" maps to multiple items: ${result.candidates.join(', ')}`;
            break;
        }

        errors.push({
          ref,
          sourceFile,
          sourceUlid: item._ulid,
          field,
          error: result.error,
          message,
        });
      } else {
        // Check if resolved target is deprecated
        if (isDeprecated(result.item)) {
          const targetTitle = (result.item as { title?: string }).title || result.ulid;
          warnings.push({
            ref,
            sourceFile,
            sourceUlid: item._ulid,
            field,
            warning: 'deprecated_target',
            message: `Reference "${ref}" points to deprecated item: ${targetTitle}`,
          });
        }

        // AC: @traits-field ac-3 - traits ref must point to trait-type item
        if (field === 'traits') {
          const targetItem = result.item as { type?: string };
          if (targetItem.type !== 'trait') {
            errors.push({
              ref,
              sourceFile,
              sourceUlid: item._ulid,
              field,
              error: 'not_found', // Reuse error type
              message: `Trait reference "${ref}" points to non-trait item (type: ${targetItem.type || 'unknown'})`,
            });
          }

          // AC: @traits-field ac-5 - warn on duplicate traits
          if (seenTraits.has(result.ulid)) {
            const targetTitle = (result.item as { title?: string }).title || result.ulid;
            warnings.push({
              ref,
              sourceFile,
              sourceUlid: item._ulid,
              field,
              warning: 'deprecated_target', // Reuse warning type for now
              message: `Duplicate trait reference "${ref}" (${targetTitle})`,
            });
          }
          seenTraits.add(result.ulid);
        }
      }
    }
  }

  return { errors, warnings };
}

/**
 * Find duplicate slugs in the index.
 * Returns map of slug → ULIDs for slugs with multiple items.
 */
export function findDuplicateSlugs(index: ReferenceIndex): Map<string, string[]> {
  const duplicates = new Map<string, string[]>();

  for (const [slug, ulids] of index.getAllSlugs()) {
    if (ulids.length > 1) {
      duplicates.set(slug, ulids);
    }
  }

  return duplicates;
}

// ============================================================
// SLUG UNIQUENESS CHECK
// ============================================================

/**
 * Result of checking slug uniqueness
 */
export interface SlugCheckSuccess {
  ok: true;
}

export interface SlugCheckConflict {
  ok: false;
  slug: string;
  existingUlid: string;
}

export type SlugCheckResult = SlugCheckSuccess | SlugCheckConflict;

/**
 * Check if proposed slugs are unique (don't conflict with existing items).
 *
 * @param index The reference index to check against
 * @param slugs Array of proposed slugs to check
 * @param excludeUlid Optional ULID to exclude from conflict check (for updates)
 * @returns Success if all slugs are available, or conflict info if one exists
 */
export function checkSlugUniqueness(
  index: ReferenceIndex,
  slugs: string[],
  excludeUlid?: string
): SlugCheckResult {
  const allSlugs = index.getAllSlugs();

  for (const slug of slugs) {
    const existingUlids = allSlugs.get(slug);
    if (existingUlids) {
      // Filter out the item being updated (if provided)
      const conflictingUlids = excludeUlid
        ? existingUlids.filter(ulid => ulid !== excludeUlid)
        : existingUlids;

      if (conflictingUlids.length > 0) {
        return {
          ok: false,
          slug,
          existingUlid: conflictingUlids[0],
        };
      }
    }
  }

  return { ok: true };
}

/**
 * Alignment tracking between specs and tasks.
 *
 * Provides bidirectional mapping from spec items to implementing tasks,
 * and detects alignment issues like orphaned specs or stale implementation status.
 */

import type { LoadedSpecItem, LoadedTask, KspecContext } from './yaml.js';
import { updateSpecItem } from './yaml.js';
import type { ReferenceIndex } from './refs.js';
import type { ImplementationStatus } from '../schema/index.js';

// ============================================================
// TYPES
// ============================================================

/**
 * Summary of a spec item's implementation status based on linked tasks
 */
export interface SpecImplementationSummary {
  specUlid: string;
  specTitle: string;
  currentStatus: ImplementationStatus;
  expectedStatus: ImplementationStatus;
  linkedTasks: LinkedTaskSummary[];
  isAligned: boolean;
}

/**
 * Summary of a task linked to a spec item
 */
export interface LinkedTaskSummary {
  taskUlid: string;
  taskTitle: string;
  taskStatus: string;
  hasNotes: boolean;
}

/**
 * Alignment warning
 */
export interface AlignmentWarning {
  type: 'orphaned_spec' | 'status_mismatch' | 'stale_implementation';
  specUlid?: string;
  specTitle?: string;
  taskUlid?: string;
  message: string;
}

// ============================================================
// ALIGNMENT INDEX
// ============================================================

/**
 * Index for tracking spec-task alignment.
 * Build once when loading, then query for alignment issues.
 */
export class AlignmentIndex {
  /** spec ULID → task ULIDs that reference it */
  private specToTasks = new Map<string, string[]>();

  /** task ULID → spec ULID it references */
  private taskToSpec = new Map<string, string>();

  /** All spec items by ULID */
  private specItems = new Map<string, LoadedSpecItem>();

  /** All tasks by ULID */
  private tasks = new Map<string, LoadedTask>();

  /**
   * Build index from loaded items
   */
  constructor(tasks: LoadedTask[], items: LoadedSpecItem[]) {
    // Index spec items
    for (const item of items) {
      this.specItems.set(item._ulid, item);
      this.specToTasks.set(item._ulid, []);
    }

    // Index tasks and build reverse mapping
    for (const task of tasks) {
      this.tasks.set(task._ulid, task);

      if (task.spec_ref) {
        // Store the raw ref - we'll resolve it when needed
        this.taskToSpec.set(task._ulid, task.spec_ref);
      }
    }
  }

  /**
   * Resolve task spec_refs and build the bidirectional index.
   * Must be called with a ReferenceIndex to resolve @refs.
   */
  buildLinks(refIndex: ReferenceIndex): void {
    for (const [taskUlid, specRef] of this.taskToSpec) {
      const result = refIndex.resolve(specRef);
      if (result.ok) {
        const specUlid = result.ulid;
        const existing = this.specToTasks.get(specUlid);
        if (existing) {
          existing.push(taskUlid);
        }
      }
    }
  }

  /**
   * Get tasks that implement a spec item
   */
  getTasksForSpec(specUlid: string): LoadedTask[] {
    const taskUlids = this.specToTasks.get(specUlid) || [];
    return taskUlids
      .map(ulid => this.tasks.get(ulid))
      .filter((t): t is LoadedTask => t !== undefined);
  }

  /**
   * Get the spec item a task implements
   */
  getSpecForTask(taskUlid: string, refIndex: ReferenceIndex): LoadedSpecItem | undefined {
    const specRef = this.taskToSpec.get(taskUlid);
    if (!specRef) return undefined;

    const result = refIndex.resolve(specRef);
    if (result.ok) {
      return this.specItems.get(result.ulid);
    }
    return undefined;
  }

  /**
   * Calculate expected implementation status based on linked task statuses
   */
  calculateExpectedStatus(specUlid: string): ImplementationStatus {
    const taskUlids = this.specToTasks.get(specUlid) || [];
    if (taskUlids.length === 0) {
      return 'not_started';
    }

    const tasks = taskUlids
      .map(ulid => this.tasks.get(ulid))
      .filter((t): t is LoadedTask => t !== undefined);

    if (tasks.length === 0) {
      return 'not_started';
    }

    // Check task statuses
    const hasInProgress = tasks.some(t => t.status === 'in_progress');
    const allCompleted = tasks.every(t => t.status === 'completed');
    const someCompleted = tasks.some(t => t.status === 'completed');

    if (allCompleted) {
      return 'implemented';
    }
    if (hasInProgress || someCompleted) {
      return 'in_progress';
    }
    return 'not_started';
  }

  /**
   * Get implementation summary for a spec item
   */
  getImplementationSummary(specUlid: string): SpecImplementationSummary | undefined {
    const spec = this.specItems.get(specUlid);
    if (!spec) return undefined;

    const taskUlids = this.specToTasks.get(specUlid) || [];
    const linkedTasks: LinkedTaskSummary[] = taskUlids
      .map(ulid => this.tasks.get(ulid))
      .filter((t): t is LoadedTask => t !== undefined)
      .map(t => ({
        taskUlid: t._ulid,
        taskTitle: t.title,
        taskStatus: t.status,
        hasNotes: t.notes.length > 0,
      }));

    const currentStatus = spec.status?.implementation || 'not_started';
    const expectedStatus = this.calculateExpectedStatus(specUlid);

    return {
      specUlid,
      specTitle: spec.title,
      currentStatus,
      expectedStatus,
      linkedTasks,
      isAligned: currentStatus === expectedStatus,
    };
  }

  /**
   * Find all alignment issues
   */
  findAlignmentWarnings(): AlignmentWarning[] {
    const warnings: AlignmentWarning[] = [];

    // Check each spec item
    for (const [specUlid, spec] of this.specItems) {
      const taskUlids = this.specToTasks.get(specUlid) || [];
      const currentStatus = spec.status?.implementation || 'not_started';
      const expectedStatus = this.calculateExpectedStatus(specUlid);

      // Orphaned spec (no tasks)
      if (taskUlids.length === 0 && currentStatus === 'not_started') {
        warnings.push({
          type: 'orphaned_spec',
          specUlid,
          specTitle: spec.title,
          message: `Spec item "${spec.title}" has no implementing tasks`,
        });
      }

      // Status mismatch
      if (currentStatus !== expectedStatus) {
        warnings.push({
          type: 'status_mismatch',
          specUlid,
          specTitle: spec.title,
          message: `Spec "${spec.title}" status is "${currentStatus}" but should be "${expectedStatus}" based on task progress`,
        });
      }
    }

    // Check completed tasks with stale spec status
    for (const [taskUlid, task] of this.tasks) {
      if (task.status === 'completed' && task.spec_ref) {
        const specRef = this.taskToSpec.get(taskUlid);
        if (specRef) {
          // Note: We already checked this via spec iteration above
          // But this provides task-centric context
        }
      }
    }

    return warnings;
  }

  /**
   * Get all spec items with their implementation summary
   */
  getAllImplementationSummaries(): SpecImplementationSummary[] {
    const summaries: SpecImplementationSummary[] = [];
    for (const specUlid of this.specItems.keys()) {
      const summary = this.getImplementationSummary(specUlid);
      if (summary) {
        summaries.push(summary);
      }
    }
    return summaries;
  }

  /**
   * Get stats about alignment
   */
  getStats(): {
    totalSpecs: number;
    specsWithTasks: number;
    alignedSpecs: number;
    orphanedSpecs: number;
  } {
    let specsWithTasks = 0;
    let alignedSpecs = 0;
    let orphanedSpecs = 0;

    for (const specUlid of this.specItems.keys()) {
      const taskUlids = this.specToTasks.get(specUlid) || [];
      if (taskUlids.length > 0) {
        specsWithTasks++;
        const summary = this.getImplementationSummary(specUlid);
        if (summary?.isAligned) {
          alignedSpecs++;
        }
      } else {
        orphanedSpecs++;
      }
    }

    return {
      totalSpecs: this.specItems.size,
      specsWithTasks,
      alignedSpecs,
      orphanedSpecs,
    };
  }
}

// ============================================================
// SYNC FUNCTIONS
// ============================================================

/**
 * Result of syncing spec implementation status
 */
export interface SyncResult {
  synced: boolean;
  specUlid: string;
  specTitle: string;
  previousStatus: ImplementationStatus;
  newStatus: ImplementationStatus;
}

/**
 * Sync a spec item's implementation status based on its linked tasks.
 * Called after task state changes (start, complete, etc.).
 *
 * @returns SyncResult if status changed, null if no change needed or no spec_ref
 */
export async function syncSpecImplementationStatus(
  ctx: KspecContext,
  task: LoadedTask,
  allTasks: LoadedTask[],
  allItems: LoadedSpecItem[],
  refIndex: ReferenceIndex
): Promise<SyncResult | null> {
  // Skip if task has no spec_ref
  if (!task.spec_ref) {
    return null;
  }

  // Resolve the spec reference
  const result = refIndex.resolve(task.spec_ref);
  if (!result.ok) {
    return null;
  }

  // Find the spec item
  const specItem = allItems.find(item => item._ulid === result.ulid);
  if (!specItem) {
    return null;
  }

  // Build alignment index to calculate expected status
  const alignmentIndex = new AlignmentIndex(allTasks, allItems);
  alignmentIndex.buildLinks(refIndex);

  const expectedStatus = alignmentIndex.calculateExpectedStatus(specItem._ulid);
  const currentStatus = specItem.status?.implementation || 'not_started';

  // No change needed
  if (currentStatus === expectedStatus) {
    return null;
  }

  // Update the spec item
  await updateSpecItem(ctx, specItem, {
    status: {
      maturity: specItem.status?.maturity || 'draft',
      implementation: expectedStatus,
    },
  });

  return {
    synced: true,
    specUlid: specItem._ulid,
    specTitle: specItem.title,
    previousStatus: currentStatus,
    newStatus: expectedStatus,
  };
}

