      const refIndex = new ReferenceIndex([], items);
      const traitIndex = new TraitIndex(items, refIndex);

      const trait = traitIndex.getTrait('01TRAIT001');
      expect(trait).toBeDefined();
      expect(trait?.acceptanceCriteria).toEqual([]);
