      const traitIndex = new TraitIndex(items, refIndex);

      const stats = traitIndex.getStats();

      expect(stats.totalTraits).toBe(0);
      expect(stats.specsWithTraits).toBe(0);
      expect(stats.avgTraitsPerSpec).toBe(0);
    });
