  expectFail?: boolean;
  /** Additional environment variables */
  env?: Record<string, string>;
}

/**
 * Result from running a kspec CLI command
 */
export interface KspecResult {
  /** Exit code (0 = success) */
  exitCode: number;
  /** Standard output (trimmed) */
  stdout: string;
  /** Standard error (trimmed) */
  stderr: string;
}

/**
 * Run a kspec CLI command
