     7→ */
     8→
     9→import type { LoadedSpecItem } from './yaml.js';
    10→import type { ReferenceIndex } from './refs.js';
    11→import type { AcceptanceCriterion } from '../schema/index.js';
    12→
    13→// ============================================================
    14→// TYPES
    15→// ============================================================
    16→
    17→/**
    18→ * Information about a trait-type spec item
    19→ */
    20→export interface TraitInfo {
    21→  ulid: string;
    22→  slug: string;
    23→  title: string;
    24→  description?: string;
    25→  acceptanceCriteria: AcceptanceCriterion[];
    26→}
    27→
    28→// ============================================================
    29→// TRAIT INDEX
    30→// ============================================================
    31→
    32→/**
    33→ * Index for tracking trait-type items and spec-trait relationships.
    34→ * Build once when loading, then query efficiently.
    35→ * AC: @trait-index ac-1, ac-2, ac-3
    36→ */
    37→export class TraitIndex {
    38→  /** All trait-type items by ULID */
    39→  private traits = new Map<string, TraitInfo>();
    40→
    41→  /** trait ULID → spec ULIDs that implement it */
    42→  private traitToSpecs = new Map<string, string[]>();
    43→
    44→  /** spec ULID → trait ULIDs it implements */
    45→  private specToTraits = new Map<string, string[]>();
    46→
    47→  /**
    48→   * Build index from loaded items
    49→   * AC: @trait-index ac-1
    50→   */
    51→  constructor(items: LoadedSpecItem[], refIndex: ReferenceIndex) {
    52→    // First pass: index all trait-type items
    53→    for (const item of items) {
    54→      if (item.type === 'trait') {
    55→        const slug = item.slugs[0] || item._ulid;
    56→        this.traits.set(item._ulid, {
    57→          ulid: item._ulid,
    58→          slug,
    59→          title: item.title,
    60→          description: item.description,
    61→          acceptanceCriteria: item.acceptance_criteria || [],
    62→        });
    63→        this.traitToSpecs.set(item._ulid, []);
    64→      }
    65→    }
    66→
    67→    // Second pass: index spec-trait relationships
    68→    for (const item of items) {
    69→      if (item.traits && item.traits.length > 0) {
    70→        const specUlid = item._ulid;
    71→        const traitUlids: string[] = [];
    72→
    73→        for (const traitRef of item.traits) {
    74→          const result = refIndex.resolve(traitRef);
    75→          if (result.ok) {
    76→            const traitUlid = result.ulid;
    77→            traitUlids.push(traitUlid);
    78→
    79→            // Add to trait → specs mapping
    80→            const specs = this.traitToSpecs.get(traitUlid);
    81→            if (specs) {
    82→              specs.push(specUlid);
    83→            }
    84→          }
    85→        }
    86→
    87→        if (traitUlids.length > 0) {
    88→          this.specToTraits.set(specUlid, traitUlids);
    89→        }
    90→      }
    91→    }
    92→  }
    93→
    94→  /**
    95→   * Get all traits implemented by a spec
    96→   */
    97→  getTraitsForSpec(specUlid: string): TraitInfo[] {
    98→    const traitUlids = this.specToTraits.get(specUlid) || [];
    99→    return traitUlids
   100→      .map(ulid => this.traits.get(ulid))
   101→      .filter((t): t is TraitInfo => t !== undefined);
   102→  }
   103→
   104→  /**
   105→   * Get all specs that implement a trait
   106→   * AC: @trait-index ac-3
   107→   */
   108→  getSpecsForTrait(traitUlid: string): string[] {
   109→    return this.traitToSpecs.get(traitUlid) || [];
   110→  }
   111→
   112→  /**
   113→   * Get all acceptance criteria inherited from implemented traits
   114→   * AC: @trait-index ac-2
   115→   */
   116→  getInheritedAC(specUlid: string): Array<{ trait: TraitInfo; ac: AcceptanceCriterion }> {
   117→    const traits = this.getTraitsForSpec(specUlid);
   118→    const inherited: Array<{ trait: TraitInfo; ac: AcceptanceCriterion }> = [];
   119→
   120→    for (const trait of traits) {
   121→      for (const ac of trait.acceptanceCriteria) {
   122→        inherited.push({ trait, ac });
   123→      }
   124→    }
   125→
   126→    return inherited;
   127→  }
   128→
   129→  /**
   130→   * Get all trait-type items
   131→   */
   132→  getAllTraits(): TraitInfo[] {
   133→    return Array.from(this.traits.values());
   134→  }
   135→
   136→  /**
   137→   * Get a specific trait by ULID
   138→   */
   139→  getTrait(traitUlid: string): TraitInfo | undefined {
   140→    return this.traits.get(traitUlid);
   141→  }
   142→
   143→  /**
   144→   * Get stats about traits
   145→   */
   146→  getStats(): {
   147→    totalTraits: number;
   148→    specsWithTraits: number;
   149→    avgTraitsPerSpec: number;
   150→  } {
   151→    const specsWithTraits = this.specToTraits.size;
   152→    const totalTraitRefs = Array.from(this.specToTraits.values()).reduce(
   153→      (sum, traits) => sum + traits.length,
   154→      0
   155→    );
   156→
   157→    return {
   158→      totalTraits: this.traits.size,
   159→      specsWithTraits,
   160→      avgTraitsPerSpec: specsWithTraits > 0 ? totalTraitRefs / specsWithTraits : 0,
   161→    };
   162→  }
   163→}
   164→

