      implementation: not_started
    traits:
      - "@trait-json-output"
    acceptance_criteria:
      - id: ac-1
        given: feature enabled
        when: user interacts
        then: responds correctly
`;

  await fs.writeFile(
    path.join(tempDir, 'modules/specs.yaml'),
    specModule
  );

  // Update manifest to include new modules
  const manifest = await fs.readFile(
    path.join(tempDir, 'kynetic.yaml'),
    'utf-8'
  );
  const updatedManifest = manifest.replace(
    'includes:\n  - modules/core.yaml',
    'includes:\n  - modules/core.yaml\n  - modules/traits.yaml\n  - modules/specs.yaml'
  );
  await fs.writeFile(
    path.join(tempDir, 'kynetic.yaml'),
    updatedManifest
  );

  console.log('\nRunning kspec item get @feature-with-trait...\n');

  // Run kspec item get
  const result = execSync(`cd ${tempDir} && kspec item get @feature-with-trait`, { encoding: 'utf-8' });
  console.log(result);

  console.log('\n\nRunning kspec item get @feature-with-trait --json...\n');
  const jsonResult = execSync(`cd ${tempDir} && kspec item get @feature-with-trait --json`, { encoding: 'utf-8' });
  const parsed = JSON.parse(jsonResult);
  console.log('Inherited traits:', JSON.stringify(parsed.inherited_traits, null, 2));

