  console.error('Error:', error.message);
  if (error.stdout) console.log('stdout:', error.stdout);
  if (error.stderr) console.log('stderr:', error.stderr);
} finally {
  // Cleanup
  execSync(`rm -rf ${tempDir}`);
}

