    const spec = {
      _ulid: '01KFCRVY8MT49H8N6JW35NN2P3',
      slugs: ['test-spec'],
      title: 'Test Spec',
      type: 'requirement',
      description: 'A spec referencing deleted trait',
      status: { maturity: 'draft', implementation: 'not_started' },
      traits: ['@deleted-trait'],
