import chalk from 'chalk';
import {
  initContext,
  buildIndexes,
  createSpecItem,
  updateSpecItem,
  addChildItem,
  checkSlugUniqueness,
  ReferenceIndex,
  type LoadedSpecItem,
} from '../../parser/index.js';
import { commitIfShadow } from '../../parser/shadow.js';
import type { SpecItemInput } from '../../schema/index.js';
