import * as fs from 'fs/promises';
import * as path from 'path';
import * as os from 'os';

const CLI = '/home/chapel/Projects/kynetic-spec/dist/cli/index.js';
const FIXTURES = '/home/chapel/Projects/kynetic-spec/tests/fixtures';

// Create temp dir and copy fixtures
const tempDir = await fs.mkdtemp(path.join(os.tmpdir(), 'trait-debug-'));
await fs.cp(FIXTURES, tempDir, { recursive: true });

// Init git
execSync('git init && git config user.email "test@test.com" && git config user.name "Test"', { cwd: tempDir });

console.log('=== Created temp dir:', tempDir);

// Add a trait
console.log('\n=== Adding trait...');
const addResult = execSync(`node ${CLI} trait add "Test Trait" --json`, {
  cwd: tempDir,
  encoding: 'utf-8',
  env: { ...process.env, KSPEC_AUTHOR: '@test' }
});
console.log('Add result:', addResult);

// Check kynetic.yaml
