try {
  const listResult = execSync(`node ${CLI} trait list --json`, {
    cwd: tempDir,
    encoding: 'utf-8',
    env: { ...process.env, KSPEC_AUTHOR: '@test' }
  });
  console.log('List result:', listResult);
} catch (e) {
  console.log('List failed:', e.stdout || e.message);
}

// Cleanup
await fs.rm(tempDir, { recursive: true, force: true });

