   139→              const acInfo = acCount > 0 ? chalk.gray(` (${acCount} AC)`) : chalk.gray(' (no AC)');
   140→
   141→              console.log(
   142→                `${chalk.gray(shortId)} ${trait.title} ${chalk.cyan(`@${trait.slug}`)}${acInfo}`
   143→              );
