   151→        process.exit(EXIT_CODES.ERROR);
   152→      }
   153→    });
   154→
   155→  // kspec trait get <ref>
   156→  // AC: @trait-cli ac-4
   157→  trait
   158→    .command('get <ref>')
   159→    .description('Show trait details')
   160→    .action(async (ref: string) => {
   161→      try {
   162→        const ctx = await initContext();
   163→        const { refIndex, traitIndex } = await buildIndexes(ctx);
   164→
   165→        const result = refIndex.resolve(ref);
   166→        if (!result.ok) {
   167→          error(errors.reference.itemNotFound(ref));
   168→          process.exit(EXIT_CODES.NOT_FOUND);
   169→        }
   170→
   171→        const item = result.item as LoadedSpecItem;
   172→
   173→        // Verify it's a trait
   174→        if (item.type !== 'trait') {
   175→          error(`Item ${ref} is not a trait (type: ${item.type})`);
   176→          process.exit(EXIT_CODES.ERROR);
   177→        }
   178→
   179→        const trait = traitIndex.getTrait(item._ulid);
   180→        if (!trait) {
   181→          error(`Trait ${ref} not found in trait index`);
   182→          process.exit(EXIT_CODES.ERROR);
   183→        }
   184→
   185→        const specsUsingTrait = traitIndex.getSpecsForTrait(item._ulid);
   186→
   187→        output(
   188→          { trait, specs_using_trait: specsUsingTrait },
   189→          () => {
   190→            console.log(chalk.bold(trait.title));
   191→            console.log(chalk.gray('─'.repeat(40)));
   192→            console.log(`ULID:      ${trait.ulid}`);
   193→            console.log(`Slug:      @${trait.slug}`);
   194→            console.log(`Type:      trait`);
   195→
   196→            if (trait.description) {
   197→              console.log('\n─── Description ───');
   198→              console.log(trait.description);
   199→            }
   200→
   201→            // AC: @trait-cli ac-4 - show acceptance criteria
   202→            if (trait.acceptanceCriteria.length > 0) {
   203→              console.log('\n─── Acceptance Criteria ───');
   204→              for (const ac of trait.acceptanceCriteria) {
   205→                console.log(chalk.cyan(`  [${ac.id}]`));
   206→                if (ac.given) console.log(`    Given: ${ac.given}`);
   207→                if (ac.when) console.log(`    When: ${ac.when}`);
   208→                if (ac.then) console.log(`    Then: ${ac.then}`);
   209→              }
   210→            }
   211→
   212→            if (specsUsingTrait.length > 0) {
   213→              console.log(chalk.gray(`\nUsed by ${specsUsingTrait.length} spec(s)`));
   214→            }
   215→          }
   216→        );
   217→      } catch (err) {
   218→        error('Failed to get trait', err);
   219→        process.exit(EXIT_CODES.ERROR);
   220→      }
   221→    });
   222→}
   223→
   224→/**
   225→ * Register item trait subcommands (for adding/removing traits from specs)
   226→ */
   227→export function registerItemTraitCommands(itemCommand: Command): void {
   228→  const traitCmd = itemCommand
   229→    .command('trait')
   230→    .description('Manage traits on spec items');
   231→
   232→  // kspec item trait add <spec-ref> <trait-ref>
   233→  // AC: @trait-cli ac-5, ac-6, ac-7
   234→  traitCmd
   235→    .command('add <specRef> <traitRef>')
   236→    .description('Add a trait to a spec item')
   237→    .action(async (specRef: string, traitRef: string) => {
   238→      try {
   239→        const ctx = await initContext();
   240→        const { refIndex, items } = await buildIndexes(ctx);
   241→
   242→        // Resolve spec
   243→        const specResult = refIndex.resolve(specRef);
   244→        if (!specResult.ok) {
   245→          error(errors.reference.itemNotFound(specRef));
   246→          process.exit(EXIT_CODES.NOT_FOUND);
   247→        }
   248→
   249→        const spec = specResult.item as LoadedSpecItem;
   250→
   251→        // Check if it's a task
   252→        if ('status' in spec && typeof spec.status === 'string') {
   253→          error(`Cannot add traits to tasks. ${specRef} is a task.`);
   254→          process.exit(EXIT_CODES.ERROR);
   255→        }
   256→
   257→        // AC: @trait-cli ac-7 - verify trait exists
   258→        const traitResult = refIndex.resolve(traitRef);
   259→        if (!traitResult.ok) {
   260→          error(`Trait not found: ${traitRef}`);
   261→          process.exit(EXIT_CODES.NOT_FOUND);
   262→        }
   263→
   264→        const traitItem = traitResult.item as LoadedSpecItem;
   265→        if (traitItem.type !== 'trait') {
   266→          error(`${traitRef} is not a trait (type: ${traitItem.type})`);
   267→          process.exit(EXIT_CODES.ERROR);
   268→        }
   269→
   270→        // AC: @trait-cli ac-6 - idempotent (no duplicate)
   271→        const currentTraits = spec.traits || [];
   272→        const traitRefString = `@${traitItem.slugs[0] || traitItem._ulid}`;
   273→
   274→        if (currentTraits.includes(traitRefString)) {
   275→          warn(`Spec already has trait ${traitRefString} (idempotent - no change)`);
   276→          output({ spec: spec._ulid, trait: traitRefString, added: false }, () => {});
   277→          return;
   278→        }
   279→
   280→        // AC: @trait-cli ac-5 - add trait to traits array
   281→        const updatedTraits = [...currentTraits, traitRefString];
   282→        await updateSpecItem(ctx, spec, { traits: updatedTraits });
   283→
   284→        const specSlug = spec.slugs[0] || refIndex.shortUlid(spec._ulid);
   285→        await commitIfShadow(ctx.shadow, 'item-trait-add', specSlug);
   286→
   287→        success(`Added trait ${traitRefString} to ${specSlug}`, {
   288→          spec: specSlug,
   289→          trait: traitRefString,
   290→          added: true,
   291→        });
   292→      } catch (err) {
   293→        error('Failed to add trait to spec', err);
   294→        process.exit(EXIT_CODES.ERROR);
   295→      }
   296→    });
   297→
   298→  // kspec item trait remove <spec-ref> <trait-ref>
   299→  // AC: @trait-cli ac-8
   300→  traitCmd
   301→    .command('remove <specRef> <traitRef>')
   302→    .description('Remove a trait from a spec item')
   303→    .action(async (specRef: string, traitRef: string) => {
   304→      try {
   305→        const ctx = await initContext();
   306→        const { refIndex } = await buildIndexes(ctx);
   307→
   308→        // Resolve spec
   309→        const specResult = refIndex.resolve(specRef);
   310→        if (!specResult.ok) {
   311→          error(errors.reference.itemNotFound(specRef));
   312→          process.exit(EXIT_CODES.NOT_FOUND);
   313→        }
   314→
   315→        const spec = specResult.item as LoadedSpecItem;
   316→
   317→        // Check if it's a task
   318→        if ('status' in spec && typeof spec.status === 'string') {
   319→          error(`Cannot remove traits from tasks. ${specRef} is a task.`);
   320→          process.exit(EXIT_CODES.ERROR);
   321→        }
   322→
   323→        // Resolve trait to get its ref format
   324→        const traitResult = refIndex.resolve(traitRef);
   325→        if (!traitResult.ok) {
   326→          error(`Trait not found: ${traitRef}`);
   327→          process.exit(EXIT_CODES.NOT_FOUND);
   328→        }
   329→
   330→        const traitItem = traitResult.item as LoadedSpecItem;
   331→        const traitRefString = `@${traitItem.slugs[0] || traitItem._ulid}`;
   332→
   333→        // AC: @trait-cli ac-8 - remove from traits array
   334→        const currentTraits = spec.traits || [];
   335→
   336→        // Check if trait is in the list
   337→        if (!currentTraits.includes(traitRefString)) {
   338→          warn(`Spec does not have trait ${traitRefString}`);
   339→          output({ spec: spec._ulid, trait: traitRefString, removed: false }, () => {});
   340→          return;
   341→        }
   342→
   343→        const updatedTraits = currentTraits.filter(t => t !== traitRefString);
   344→        await updateSpecItem(ctx, spec, { traits: updatedTraits });
   345→
   346→        const specSlug = spec.slugs[0] || refIndex.shortUlid(spec._ulid);
   347→        await commitIfShadow(ctx.shadow, 'item-trait-remove', specSlug);
   348→
   349→        success(`Removed trait ${traitRefString} from ${specSlug}`, {
   350→          spec: specSlug,
   351→          trait: traitRefString,
   352→          removed: true,
   353→        });
   354→      } catch (err) {
   355→        error('Failed to remove trait from spec', err);
   356→        process.exit(EXIT_CODES.ERROR);
   357→      }
   358→    });
   359→}
   360→

