// MAIN VALIDATION
// ============================================================

/**
 * Run full validation on a kspec project
 */
export async function validate(
  ctx: KspecContext,
  options: ValidateOptions = {}
): Promise<ValidationResult> {
  // Default: run all checks
  const runSchema = options.schema !== false;
  const runRefs = options.refs !== false;
  const runOrphans = options.orphans !== false;
  const runCompleteness = options.completeness !== false;

  const result: ValidationResult = {
    valid: true,
    schemaErrors: [],
    refErrors: [],
    refWarnings: [],
    orphans: [],
    completenessWarnings: [],
    stats: {
      filesChecked: 0,
      itemsChecked: 0,
      tasksChecked: 0,
    },
  };

  const allTasks: LoadedTask[] = [];
  const allItems: LoadedSpecItem[] = [];

  // Validate manifest
  if (ctx.manifestPath && runSchema) {
    const manifestErrors = await validateManifestFile(ctx.manifestPath);
    result.schemaErrors.push(...manifestErrors);
    result.stats.filesChecked++;
  }

  // Find and validate task files
  const taskFiles = await findTaskFiles(ctx.rootDir);
  const specTaskFiles = await findTaskFiles(path.join(ctx.rootDir, 'spec'));
  const allTaskFiles = [...new Set([...taskFiles, ...specTaskFiles])];

  for (const taskFile of allTaskFiles) {
    if (runSchema) {
      const taskErrors = await validateTasksFile(taskFile);
      result.schemaErrors.push(...taskErrors);
    }
    result.stats.filesChecked++;

    // Load tasks for ref validation
    try {
      const raw = await readYamlFile<unknown>(taskFile);
      let taskList: unknown[] = [];

      if (Array.isArray(raw)) {
        taskList = raw;
      } else if (raw && typeof raw === 'object' && 'tasks' in raw) {
        taskList = (raw as { tasks: unknown[] }).tasks || [];
      }

      for (const t of taskList) {
        const parsed = TaskSchema.safeParse(t);
        if (parsed.success) {
          allTasks.push({ ...parsed.data, _sourceFile: taskFile });
          result.stats.tasksChecked++;
        }
      }
    } catch {
      // Already reported in schema validation
    }
  }

  // Validate spec files (from includes)
  if (ctx.manifest && ctx.manifestPath) {
    const manifestDir = path.dirname(ctx.manifestPath);
    const includes = ctx.manifest.includes || [];

    for (const include of includes) {
      const expandedPaths = await expandIncludePattern(include, manifestDir);

      for (const filePath of expandedPaths) {
        if (runSchema) {
          const specErrors = await validateSpecFile(filePath);
          result.schemaErrors.push(...specErrors);
        }
        result.stats.filesChecked++;

        // Load items for ref validation
        try {
          const items = await loadSpecFile(filePath);
          allItems.push(...items);
          result.stats.itemsChecked += items.length;
        } catch {
          // Already reported in schema validation
        }
      }
    }
  }

  // Load meta items for reference validation
  // AC: @agent-definitions ac-agent-3
  const metaCtx = await loadMetaContext(ctx);
  const allMetaItems = [
    ...metaCtx.agents,
    ...metaCtx.workflows,
    ...metaCtx.conventions,
    ...metaCtx.observations,
  ];

  // Reference validation
  if (runRefs && (allTasks.length > 0 || allItems.length > 0 || allMetaItems.length > 0)) {
    const index = new ReferenceIndex(allTasks, allItems, allMetaItems);
    const refResult = validateRefs(index, allTasks, allItems);
    result.refErrors = refResult.errors;
    result.refWarnings = refResult.warnings;

    // Orphan detection
    if (runOrphans) {
      result.orphans = findOrphans(allTasks, allItems, index);
    }

    // Completeness validation
    // AC: @spec-completeness ac-1, ac-2, ac-3
    // AC: @trait-validation ac-3
    if (runCompleteness) {
      // Build trait index for trait AC coverage validation
      const traitIndex = new TraitIndex(allItems, index);
      result.completenessWarnings = await checkCompleteness(allItems, index, ctx.rootDir, traitIndex);
    }
  }

  // Meta manifest validation (AC-meta-manifest-2, AC-meta-manifest-3)
  const metaManifestPath = await findMetaManifest(ctx.specDir);
  if (metaManifestPath) {
    // Use metaCtx already loaded above
    result.metaStats = {
      agents: metaCtx.agents.length,
      workflows: metaCtx.workflows.length,
      conventions: metaCtx.conventions.length,
      observations: metaCtx.observations.length,
    };

    // Validate meta manifest schema with strict ULID validation
    if (runSchema) {
      const metaErrors = await validateMetaManifestFile(metaManifestPath);
      // Prefix all meta errors with "meta:"
      for (const err of metaErrors) {
        err.path = err.path ? `meta:${err.path}` : 'meta:';
      }
      result.schemaErrors.push(...metaErrors);
      result.stats.filesChecked++;
    }
  }

  // Set valid flag
  result.valid = result.schemaErrors.length === 0 && result.refErrors.length === 0;

  return result;
}

/**
 * Trait tracking and inheritance system.
 *
 * Provides efficient lookup of trait-type items and trait-spec relationships.
 * Follows the pattern of ReferenceIndex and AlignmentIndex - built once from
 * loaded items, queried efficiently.
 */

import type { LoadedSpecItem } from './yaml.js';
import type { ReferenceIndex } from './refs.js';
import type { AcceptanceCriterion } from '../schema/index.js';

// ============================================================
// TYPES
// ============================================================

/**
 * Information about a trait-type spec item
 */
export interface TraitInfo {
  ulid: string;
  slug: string;
  title: string;
  description?: string;
  acceptanceCriteria: AcceptanceCriterion[];
}

// ============================================================
// TRAIT INDEX
// ============================================================

/**
 * Index for tracking trait-type items and spec-trait relationships.
 * Build once when loading, then query efficiently.
 * AC: @trait-index ac-1, ac-2, ac-3
 */
export class TraitIndex {
  /** All trait-type items by ULID */
  private traits = new Map<string, TraitInfo>();

  /** trait ULID → spec ULIDs that implement it */
  private traitToSpecs = new Map<string, string[]>();

  /** spec ULID → trait ULIDs it implements */
  private specToTraits = new Map<string, string[]>();

  /**
   * Build index from loaded items
   * AC: @trait-index ac-1
   */
  constructor(items: LoadedSpecItem[], refIndex: ReferenceIndex) {
    // First pass: index all trait-type items
    for (const item of items) {
      if (item.type === 'trait') {
        const slug = item.slugs[0] || item._ulid;
        this.traits.set(item._ulid, {
          ulid: item._ulid,
          slug,
          title: item.title,
          description: item.description,
          acceptanceCriteria: item.acceptance_criteria || [],
        });
        this.traitToSpecs.set(item._ulid, []);
      }
    }

    // Second pass: index spec-trait relationships
    for (const item of items) {
      if (item.traits && item.traits.length > 0) {
        const specUlid = item._ulid;
        const traitUlids: string[] = [];

        for (const traitRef of item.traits) {
          const result = refIndex.resolve(traitRef);
          if (result.ok) {
            const traitUlid = result.ulid;
            traitUlids.push(traitUlid);

            // Add to trait → specs mapping
            const specs = this.traitToSpecs.get(traitUlid);
            if (specs) {
              specs.push(specUlid);
            }
          }
        }

        if (traitUlids.length > 0) {
          this.specToTraits.set(specUlid, traitUlids);
        }
      }
    }
  }

  /**
   * Get all traits implemented by a spec
   */
  getTraitsForSpec(specUlid: string): TraitInfo[] {
    const traitUlids = this.specToTraits.get(specUlid) || [];
    return traitUlids
      .map(ulid => this.traits.get(ulid))
      .filter((t): t is TraitInfo => t !== undefined);
  }

  /**
   * Get all specs that implement a trait
   * AC: @trait-index ac-3
   */
  getSpecsForTrait(traitUlid: string): string[] {
    return this.traitToSpecs.get(traitUlid) || [];
  }

  /**
   * Get all acceptance criteria inherited from implemented traits
   * AC: @trait-index ac-2
   */
  getInheritedAC(specUlid: string): Array<{ trait: TraitInfo; ac: AcceptanceCriterion }> {
    const traits = this.getTraitsForSpec(specUlid);
    const inherited: Array<{ trait: TraitInfo; ac: AcceptanceCriterion }> = [];

    for (const trait of traits) {
      for (const ac of trait.acceptanceCriteria) {
        inherited.push({ trait, ac });
      }
    }

    return inherited;
  }

  /**
   * Get all trait-type items
   */
  getAllTraits(): TraitInfo[] {
    return Array.from(this.traits.values());
  }

  /**
   * Get a specific trait by ULID
   */
  getTrait(traitUlid: string): TraitInfo | undefined {
    return this.traits.get(traitUlid);
  }

  /**
   * Get stats about traits
   */
  getStats(): {
    totalTraits: number;
    specsWithTraits: number;
    avgTraitsPerSpec: number;
  } {
    const specsWithTraits = this.specToTraits.size;
    const totalTraitRefs = Array.from(this.specToTraits.values()).reduce(
      (sum, traits) => sum + traits.length,
      0
    );

    return {
      totalTraits: this.traits.size,
      specsWithTraits,
      avgTraitsPerSpec: specsWithTraits > 0 ? totalTraitRefs / specsWithTraits : 0,
    };
  }
}

