    const escapedStdin = stdinWithNewline.replace(/'/g, "'\\''");
    cmd = `printf '%s' '${escapedStdin}' | node ${CLI_PATH} ${args}`;
  } else {
    cmd = `node ${CLI_PATH} ${args}`;
  }

