      await commitIfShadow(ctx.shadow, 'item-trait-add', specSlug);

      success(`Added trait ${traitRefString} to ${specSlug}`, {
        spec: specSlug,
        trait: traitRefString,
        added: true,
      });
    } catch (err) {
      error('Failed to add trait to spec', err);
      process.exit(EXIT_CODES.ERROR);
    }
  });

