    cwd: repoPath,
    encoding: 'utf-8',
    stdio: ['ignore', 'pipe', 'pipe']
  });

  return { success: true, currentBranch: branchResult.stdout.trim() };
}

/**
 * Get current branch name
 */
function getCurrentBranch(repoPath: string): string {
  const branchResult = spawnSync('git', ['branch', '--show-current'], {
    cwd: repoPath,
    encoding: 'utf-8',
    stdio: ['ignore', 'pipe', 'pipe']
  });

  return branchResult.stdout.trim() || 'main';
}

export const cloneForTestingCommand = new Command('clone-for-testing')
  .description('Create isolated repo copy for testing')
  .argument('[source]', 'Source repo path (default: current repo)', process.cwd())
  .argument('[dest]', 'Destination path (default: temp directory)')
  .option('--branch <name>', 'Branch to checkout after cloning')
  .option('--json', 'Output result as JSON')
  .action(async (source: string, dest: string | undefined, options: { branch?: string; json?: boolean }) => {
    try {
