/**
 * Run a git command in a directory
 *
 * @param cmd - Git command (without 'git' prefix)
 * @param cwd - Working directory
 */
export function git(cmd: string, cwd: string): void {
  execSync(`git ${cmd}`, { cwd, stdio: 'pipe' });
}

