try {
  const stdout = execSync(cmd, {
    cwd,
    encoding: 'utf-8',
    env: { ...process.env, KSPEC_AUTHOR: '@test', ...env },
    shell: stdin !== undefined ? '/bin/sh' : undefined,
  });
  return { exitCode: 0, stdout: stdout.trim(), stderr: '' };
} catch (error: unknown) {
  const execError = error as {
    status?: number;
    stdout?: string;
    stderr?: string;
